/**
 * Personalized card moves — fixed bank + decision tree (pokegit-moves-spec.md).
 *
 * Moves are selected from MOVE_BANK via thresholds on flat SignalValues, not
 * generated by an LLM. Only move ids are cached on the profile; name, type,
 * power, and description are always resolved live from the bank on read.
 *
 * Each signal family (all tiers of a given `signal`) shares one consistent
 * `type`, the same way a real move family (Ember -> Flamethrower -> Fire
 * Blast) stays a single type across power tiers.
 */

import type {
  DerivedSignals,
  PokemonType,
  RawGitHubData,
  SelectedMove,
} from "@/lib/types";

/** Card display shape for a selected move (pips, damage, flavor). */
export interface CardMove {
  name: string;
  /** Energy cost, one pip per entry. */
  cost: PokemonType[];
  damage: string;
  text: string;
}

// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------

export type SignalCategory =
  | "commit_timing"
  | "streak_consistency"
  | "collaboration"
  | "language_stack"
  | "repo_scale"
  | "commit_style";

export interface Move {
  id: string;
  name: string;
  type: PokemonType;
  power: number;
  category: SignalCategory;
  signal: string;
  /** 1 = mildest, higher = more extreme within the same signal. */
  tier: number;
  threshold: {
    metric: keyof SignalValues;
    /** Inclusive lower bound. */
    min?: number;
    /** Exclusive upper bound — keeps tiers within a signal non-overlapping. */
    max?: number;
  };
  description: string;
}

/**
 * Flat metrics the move bank thresholds against. Computed from DerivedSignals
 * + raw GitHub aggregates — no extra API calls.
 *
 * Fraction fields are 0–1. Counts/days/lengths are raw units.
 */
export interface SignalValues {
  pctCommitsAfterMidnight: number;
  pctCommitsEarlyMorning: number;
  pctCommitsEvening: number;
  pctCommitsWeekend: number;
  longestStreakDays: number;
  currentStreakDays: number;
  longestGapDays: number;
  dailyVariance: number;
  activeDays: number;
  totalReviews: number;
  totalPRs: number;
  reviewsPerCommit: number;
  collabRatio: number;
  languageCount: number;
  primaryLanguagePct: number;
  languageConcentration: number;
  repoCount: number;
  starCount: number;
  starConcentration: number;
  starsPerRepo: number;
  followerCount: number;
  avgCommitMessageLength: number;
  maxDailyContributions: number;
  meanDailyContributions: number;
  totalCommits: number;
}

// ---------------------------------------------------------------------------
// Signal computation
// ---------------------------------------------------------------------------

export function computeSignalValues(
  raw: RawGitHubData,
  signals: DerivedSignals,
): SignalValues {
  const commits = raw.contributions.totalCommitContributions;
  return {
    pctCommitsAfterMidnight: signals.timeOfDay.lateNight,
    pctCommitsEarlyMorning: signals.timeOfDay.earlyMorning,
    pctCommitsEvening: signals.timeOfDay.evening,
    pctCommitsWeekend: signals.weekendShare,
    longestStreakDays: signals.streaks.longest,
    currentStreakDays: signals.streaks.current,
    longestGapDays: signals.streaks.longestGap,
    dailyVariance: signals.dailyVariance,
    activeDays: signals.streaks.activeDays,
    totalReviews: signals.reviewsGiven,
    totalPRs: raw.pullRequestsOpened,
    reviewsPerCommit: signals.reviewsPerCommit,
    collabRatio: signals.reviewsPerCommit + signals.issuesPerCommit,
    languageCount: signals.meaningfulLanguageCount,
    primaryLanguagePct: signals.topLanguageShare,
    languageConcentration: signals.languageConcentration,
    repoCount: signals.nonForkRepoCount,
    starCount: signals.totalStars,
    starConcentration: signals.starConcentration,
    starsPerRepo: signals.starsPerRepo,
    followerCount: raw.profile.followers,
    avgCommitMessageLength: signals.avgCommitMessageLength,
    maxDailyContributions: signals.maxDailyContributions,
    meanDailyContributions: signals.meanDailyContributions,
    totalCommits: commits,
  };
}

