const CATEGORY_ORDER: SignalCategory[] = [
  "commit_timing",
  "streak_consistency",
  "collaboration",
  "language_stack",
  "repo_scale",
  "commit_style",
];

// ---------------------------------------------------------------------------
// Decision tree
// ---------------------------------------------------------------------------

interface RankedMove {
  move: Move;
  value: number;
  strength: number;
}

function inThreshold(
  value: number,
  threshold: Move["threshold"],
): boolean {
  if (!Number.isFinite(value)) return false;
  if (threshold.min != null && value < threshold.min) return false;
  if (threshold.max != null && value >= threshold.max) return false;
  // A threshold with neither min nor max would match everything — reject.
  if (threshold.min == null && threshold.max == null) return false;
  return true;
}

/**
 * How far the value sits past the tier's entry threshold, normalized to ~0–1+.
 * Higher = more distinctive / extreme within that tier band.
 *
 * For ascending signals (higher = more extreme) strength grows from `min`.
 * For low-is-extreme bands (tier rises as the value falls, e.g. language
 * concentration) strength grows toward the lower end of the band.
 */
export function moveStrength(move: Move, value: number): number {
  const { min, max } = move.threshold;
  const tierBias = move.tier * 0.01; // tiny tie-break favoring higher tiers
  const lowIsExtreme =
    move.signal === "language_concentration" ||
    (move.signal === "commit_message_length" && move.id === "one_liner");

  if (min != null && max != null) {
    const span = max - min;
    if (span <= 0) return tierBias;
    if (lowIsExtreme || min === 0) {
      return (max - value) / span + tierBias;
    }
    return (value - min) / span + tierBias;
  }
  if (min != null) {
    // Open-ended high tier: distance past the floor, scaled by the floor.
    const scale = min > 0 ? min : 1;
    return (value - min) / scale + tierBias;
  }
  if (max != null) {
    const scale = max > 0 ? max : 1;
    return (max - value) / scale + tierBias;
  }
  return tierBias;
}

function rankMatches(signals: SignalValues): RankedMove[] {
  const matched: RankedMove[] = [];

  for (const move of MOVE_BANK) {
    const value = signals[move.threshold.metric];
    if (typeof value !== "number" || !inThreshold(value, move.threshold)) {
      continue;
    }
    matched.push({
      move,
      value,
      strength: moveStrength(move, value),
    });
  }

  // Within each signal, keep only the highest tier (guards overlapping bands).
  const bestBySignal = new Map<string, RankedMove>();
  for (const entry of matched) {
    const existing = bestBySignal.get(entry.move.signal);
    if (!existing || entry.move.tier > existing.move.tier) {
      bestBySignal.set(entry.move.signal, entry);
    }
  }

  return [...bestBySignal.values()].sort((a, b) => {
    if (b.strength !== a.strength) return b.strength - a.strength;
    if (b.move.tier !== a.move.tier) return b.move.tier - a.move.tier;
    return b.move.power - a.move.power;
  });
}

function toSelected(move: Move): SelectedMove {
  return {
    id: move.id,
    name: move.name,
    type: move.type,
    power: move.power,
    description: move.description,
    category: move.category,
    signal: move.signal,
    tier: move.tier,
  };
}

/** Bank + defaults, indexed by id for O(1) hydration after cache reads. */
const MOVE_BY_ID: Map<string, Move> = (() => {
  const map = new Map<string, Move>();
  for (const move of MOVE_BANK) map.set(move.id, move);
  for (const move of Object.values(DEFAULT_MOVES)) map.set(move.id, move);
  return map;
})();

/** Resolve a cached move id to current bank copy (name/description/etc.). */
export function resolveMove(id: string): SelectedMove {
  const move = MOVE_BY_ID.get(id);
  if (!move) {
    return toSelected(DEFAULT_MOVES.commit_style);
  }
  return toSelected(move);
}

/** Hydrate a cached `[id, id]` pair into display-ready SelectedMoves. */
export function resolveMoves(
  ids: readonly [string, string],
): [SelectedMove, SelectedMove] {
  return [resolveMove(ids[0]), resolveMove(ids[1])];
}

function pickDefault(
  usedCategories: Set<SignalCategory>,
  usedIds: Set<string>,
): Move | null {
  for (const category of CATEGORY_ORDER) {
    if (usedCategories.has(category)) continue;
    const fallback = DEFAULT_MOVES[category];
    if (!usedIds.has(fallback.id)) return fallback;
  }
  // Last resort: any unused default.
  for (const category of CATEGORY_ORDER) {
    const fallback = DEFAULT_MOVES[category];
    if (!usedIds.has(fallback.id)) return fallback;
  }
  return null;
}

/**
 * Select exactly two moves from different categories, ranked by strength.
 * Falls back to per-category defaults when GitHub data is too sparse.
 */
export function selectMoves(signals: SignalValues): [SelectedMove, SelectedMove] {
  const ranked = rankMatches(signals);
  const picked: Move[] = [];
  const usedCategories = new Set<SignalCategory>();
  const usedIds = new Set<string>();

  // Slot 1: strongest match overall.
  if (ranked[0]) {
    picked.push(ranked[0].move);
    usedCategories.add(ranked[0].move.category);
    usedIds.add(ranked[0].move.id);
  }

  // Slot 2: strongest match from a different category.
  for (const entry of ranked) {
    if (picked.length >= 2) break;
    if (usedCategories.has(entry.move.category)) continue;
    if (usedIds.has(entry.move.id)) continue;
    picked.push(entry.move);
    usedCategories.add(entry.move.category);
    usedIds.add(entry.move.id);
  }

  // If category diversity blocked a second pick, take next-highest regardless.
  if (picked.length < 2) {
    for (const entry of ranked) {
      if (picked.length >= 2) break;
      if (usedIds.has(entry.move.id)) continue;
      // Still prefer a new category when possible; only relax if necessary.
      if (usedCategories.has(entry.move.category) && picked.length === 1) {
        continue;
      }
      picked.push(entry.move);
      usedCategories.add(entry.move.category);
      usedIds.add(entry.move.id);
    }
  }

  // Absolute last resort for slot 2: ignore category constraint among matches.
  if (picked.length < 2) {
    for (const entry of ranked) {
      if (usedIds.has(entry.move.id)) continue;
      picked.push(entry.move);
      usedCategories.add(entry.move.category);
      usedIds.add(entry.move.id);
      break;
    }
  }

  // Fill remaining slots from designated defaults.
  while (picked.length < 2) {
    const fallback = pickDefault(usedCategories, usedIds);
    if (!fallback) break;
    picked.push(fallback);
    usedCategories.add(fallback.category);
    usedIds.add(fallback.id);
  }

  // Should be unreachable — defaults cover every category.
  while (picked.length < 2) {
    picked.push(DEFAULT_MOVES.commit_style);
  }

  return [toSelected(picked[0]), toSelected(picked[1])];
}

export function selectMovesForProfile(
  raw: RawGitHubData,
  signals: DerivedSignals,
): [SelectedMove, SelectedMove] {
  return selectMoves(computeSignalValues(raw, signals));
}

/** Map selected moves into the card's display shape (pips, damage, text). */
export function toCardMoves(moves: [SelectedMove, SelectedMove]): CardMove[] {
  return moves.map((move) => {
    const pipCount =
      move.power < 55 ? 1 : move.power < 85 ? 2 : 3;
    return {
      name: move.name,
      cost: Array.from({ length: pipCount }, () => move.type),
      damage: move.tier >= 3 ? `${move.power}+` : String(move.power),
      text: move.description,
    };
  });
}